"""Section-exclusive questions, all taught in the introductory book."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parent.parent
rows=[]
def q(category,prompt,correct,wrong,why,level='Foundation'):
 index=len(rows);options=[correct,*wrong];shift=index%4;options=options[-shift:]+options[:-shift] if shift else options
 rows.append(dict(id=f'y10-alcohols-acids-{index+1:03}',category=category,difficulty=level,prompt=prompt,options=options,answer=shift,explanation=why))
c='Reading structures and functional groups'
q(c,'What does one line in the structural formulas represent?','One covalent bond, a shared pair of electrons.',['One whole molecule.','One free proton.','A double bond with two shared pairs.'],'One line represents one shared electron pair; two lines represent a double bond.')
q(c,'In CH₃, what does the subscript ₃ count?','Three hydrogen atoms attached to that carbon.',['Three carbon atoms.','Three oxygen atoms.','Three complete ethanol molecules.'],'A subscript applies to the element immediately before it: H₃ means three H atoms.')
q(c,'What is the total molecular formula of CH₃–CH₂–OH?','C₂H₆O',['C₂H₅O','CH₆O₂','C₃H₆O'],'Count two C, 3 + 2 + 1 = 6 H, and one O.','Application')
q(c,'Which group identifies the simple alcohols studied here?','A bonded –OH on a saturated carbon, outside a carboxyl group.',['Any O and H anywhere in a molecule.','Only a C=O group.','A free hydroxide ion OH⁻.'],'An alcohol hydroxyl is bonded within the molecule; the complete neighbouring structure matters.')
q(c,'Which arrangement is the complete carboxyl group?','–C(=O)–OH',['–CH₂–OH only','–CH₃','–OH⁻'],'The same carbon has a C=O double bond and a single bond to O–H.')
q(c,'In the acid drawings, which atom joins both the upper O and lower OH branches?','The same carboxyl carbon.',['Two unrelated carbon atoms.','A sodium atom.','The H atom in OH.'],'C is double-bonded to O above and single-bonded to OH below.','Application')
q(c,'How many bonds, counting a double bond as two, surround the carboxyl carbon?','Four',['Two','Three','Five'],'C=O contributes two, C–OH one and the bond to the attached group one: 2 + 1 + 1 = 4.','Application')
q(c,'What does a structural formula show that a molecular formula alone may not?','How the atoms are connected.',['Only the liquid volume.','The exact reaction time.','The temperature of the sample.'],'A molecular formula counts atoms; a structural formula adds connectivity.')
q(c,'Why is ethanoic acid not classified as an alcohol just because it contains OH?','Its OH belongs to a complete –COOH group on a carbonyl carbon.',['It contains no oxygen.','OH is never bonded to hydrogen.','Every acid must contain sodium.'],'Read C=O and O–H together on the same carbon.','Challenge')
q(c,'An acid formula is redrawn with C=O tilted upward and OH downward. What has changed?','The display of the same connectivity, not the identity of the compound.',['The number of carbon atoms.','The acid has necessarily become an alcohol.','A new atom has been created.'],'The drawing directions help reading; rotating a drawing does not change which atoms are bonded.','Challenge')
c='Naming alcohols and carboxylic acids'
q(c,'What is the systematic name of CH₃OH?','Methanol',['Ethanol','Methanoic acid','Propan-1-ol'],'One carbon gives meth-, and the alcohol group gives –ol.')
q(c,'Name CH₃–CH₂–OH.','Ethanol',['Ethanoic acid','Methanol','Butan-1-ol'],'Two carbons give eth-; the alcohol ending is –ol.')
q(c,'Name CH₃–CH₂–CH₂–OH using the lowest OH position.','Propan-1-ol',['Propan-3-ol','Propanoic acid','Ethanol'],'Number from the OH end: three carbons, OH at carbon 1.','Application')
q(c,'Name CH₃–CH(OH)–CH₃.','Propan-2-ol',['Propan-1-ol','Propanoic acid','Butan-2-ol'],'The three-carbon chain has OH on its middle carbon, carbon 2.','Application')
q(c,'What is the preferred name for CH₃–CH₂–CH₂–CH₂–OH in this lesson?','Butan-1-ol',['Butan-4-ol','Propan-1-ol','Butanoic acid'],'There are four carbons; numbering from OH gives the lowest locant, 1.','Challenge')
q(c,'What is the systematic name of H–C(=O)–OH?','Methanoic acid',['Methanol','Ethanoic acid','Ethanol'],'The carboxyl carbon is the only carbon: methanoic acid.')
q(c,'Name CH₃COOH, remembering the carboxyl carbon.','Ethanoic acid',['Methanoic acid','Ethanol','Propanoic acid'],'Count the CH₃ carbon and the COOH carbon: two.','Application')
q(c,'Name CH₃–CH₂–COOH.','Propanoic acid',['Ethanoic acid','Propan-1-ol','Butanoic acid'],'There are three carbons including the carboxyl carbon.','Application')
q(c,'What is the systematic name of CH₃–CH₂–CH₂–COOH?','Butanoic acid',['Propanoic acid','Butan-1-ol','Ethanoic acid'],'Four carbon atoms give but-, followed by the carboxylic-acid ending –oic acid.','Challenge')
q(c,'Which statement about acetic acid is correct?','It is a common name for ethanoic acid.',['It is another name for ethanol.','It is always sodium ethanoate.','It is the systematic name of a four-carbon acid.'],'Ethanoic acid and acetic acid name the same compound. Sodium ethanoate is a salt, not unchanged ethanoic acid.')
c='Alcohol properties production and uses'
q(c,'What is a solvent?','A substance that dissolves another substance.',['A formula subscript.','A gas that must turn limewater milky.','A number before a formula.'],'Ethanol can act as a solvent in formulated products.')
q(c,'What do the short-chain alcohols here share despite different chain lengths?','The alcohol hydroxyl functional group.',['Exactly the same total carbon count.','A carboxyl group in every molecule.','A free sodium ion.'],'Methanol, ethanol and propan-1-ol have different carbon counts but share the alcohol pattern.')
q(c,'In the ordinary dilute-water comparison, how is ethanol described?','Approximately neutral.',['Identical to sodium hydroxide.','A strongly acidic carboxylic acid.','Necessarily a concentrated base.'],'Its bonded OH is not a free hydroxide ion, and ethanol is approximately neutral in this comparison.')
q(c,'Which products form in the simplified yeast fermentation of glucose?','Ethanol and carbon dioxide.',['Ethanoic acid only.','Sodium ethanoate and hydrogen.','Sodium hydroxide and water.'],'C₆H₁₂O₆ → 2C₂H₅OH + 2CO₂.')
q(c,'What is the role of yeast enzymes in the fermentation model?','They act as biological catalysts.',['They supply new carbon atoms from nothing.','They are the carboxyl carbon.','They are position numbers in an alcohol name.'],'An enzyme is a biological catalyst that speeds the reaction without being consumed overall.')
q(c,'Which condition belongs to the simplified yeast fermentation described in the book?','Oxygen-poor conditions.',['A guarantee that ethanoic acid is the only product.','The same process as neutralising vinegar with NaOH.','No glucose molecules present.'],'Keep oxygen-poor fermentation distinct from ethanol oxidation in vinegar production.','Application')
q(c,'In 2C₂H₅OH, what does the coefficient 2 multiply?','The entire ethanol formula.',['Only the last hydrogen atom.','Only the oxygen atom.','The acidity of the liquid.'],'A coefficient counts complete molecules; it does not change the formula inside each molecule.','Application')
q(c,'How many carbon atoms are in two ethanol molecules?','Four',['Two','Six','Eight'],'Each ethanol contains two carbons, so 2 × 2 = 4.','Application')
q(c,'Which statement best describes the water-solubility trend taught for these alcohols?','A longer carbon chain generally reduces water solubility, even when OH remains.',['Adding a carbon always removes the OH group.','All alcohols contain no oxygen.','Solubility means the number of bonds on carbon.'],'The carbon-containing part becomes larger while the hydroxyl group is still present.','Challenge')
q(c,'Why does the name “alcohol” not guarantee that a substance is suitable for drinking?','It is a chemical family name; different members have different properties and hazards.',['It means every member is ethanol.','It means a molecule contains no carbon.','It means all alcohols are dilute acids.'],'Methanol and ethanol are different compounds; the book uses family names to describe chemistry.','Challenge')
c='Carboxylic acids strength and concentration'
q(c,'What does “aqueous” mean?','Dissolved in water.',['Containing no atoms.','Always a pure acid.','Only in the gas state.'],'Vinegar is an aqueous solution containing ethanoic acid.')
q(c,'What does it mean that ethanoic acid is weak in water?','Only a proportion of its molecules ionise.',['There must be very little acid per litre.','It contains no hydrogen.','All its molecules are sodium ions.'],'Weak describes partial ionisation; dilute describes concentration.')
q(c,'What does “dilute” describe?','A relatively low concentration.',['The absence of carbonyl groups.','A molecule with only one bond.','Complete ionisation in every case.'],'Concentration concerns amount per stated amount or volume of solution.')
q(c,'Which question is about acid strength rather than concentration?','How extensively does the acid ionise under the stated conditions?',['How much solution is in the bottle?','How many millilitres were poured?','How much acid is present per solution volume?'],'Strength concerns ionisation; amount per solution volume concerns concentration.','Application')
q(c,'In CH₃COOH ⇌ CH₃COO⁻ + H⁺, which species is the ethanoate ion?','CH₃COO⁻',['CH₃COOH','H₂O','CH₃CH₂OH'],'The acid has donated H⁺, leaving the negatively charged ethanoate ion.')
q(c,'What does the raised minus sign in CH₃COO⁻ indicate?','An electrical charge on the ion.',['One fewer carbon atom.','The boiling point.','A fourth type of oxygen atom.'],'An ion is an atom or group with an electrical charge.')
q(c,'How should H⁺ in an aqueous acid equation be understood?','As convenient shorthand for a proton associated with water molecules.',['As a bare proton permanently isolated from all water.','As a neutral ethanol molecule.','As the symbol for carbon dioxide.'],'H⁺ is hydrated in water; the simplified equation omits that detail.','Application')
q(c,'At about 25 °C, which pH is neutral for water?','7',['0','2','14'],'The book uses pH 7 as neutral for water at about 25 °C.')
q(c,'Can the word “weak” alone give the exact pH of an ethanoic-acid solution?','No; concentration and the solution conditions also matter.',['Yes; every weak acid solution is exactly pH 7.','Yes; weak always means pH 0.','Yes; weak means no ions exist.'],'Weak does not specify a unique concentration or pH.','Challenge')
q(c,'Why is “all weak acid solutions have one fixed percentage ionised” unreliable?','The extent of ionisation can also depend on concentration and conditions.',['Weak acids have no functional group.','Dilution creates new carbon atoms.','The carboxyl carbon disappears in water.'],'Weak is a description of acid behaviour; it is not one fixed ionisation percentage for every solution.','Challenge')
c='Acid reactions and observations'
q(c,'What products form when ethanoic acid neutralises sodium hydroxide?','Sodium ethanoate and water.',['Ethanol and oxygen.','Methanol and hydrogen.','Carbon dioxide only.'],'CH₃COOH + NaOH → CH₃COONa + H₂O.')
q(c,'What is a salt in the ionic-compound sense used here?','A compound made from positive and negative ions.',['Any molecule containing bonded OH.','A double bond to oxygen.','A position number in a name.'],'Sodium ethanoate contains sodium ions and ethanoate ions.')
q(c,'Does the word neutralisation guarantee that any chosen mixture finishes at pH 7?','No; the final solution depends on substances and amounts mixed.',['Yes, for any quantities whatsoever.','Yes, even without a base.','No, because neutralisation cannot make water.'],'Neutralisation names the reaction, not a universal final-pH guarantee.','Application')
q(c,'Which gas is expected from vinegar reacting with sodium hydrogencarbonate?','Carbon dioxide',['Hydrogen','Oxygen','Nitrogen'],'The acid–hydrogencarbonate reaction gives a salt, water and CO₂.')
q(c,'What is another familiar name for sodium hydrogencarbonate?','Baking soda',['Ethanol','Limewater','Ethanoic acid'],'Sodium hydrogencarbonate is NaHCO₃, commonly called baking soda.')
q(c,'What is effervescence?','Visible formation of gas bubbles.',['A guarantee that the liquid is boiling.','The dissolution of all carbon atoms.','A name ending for alcohols.'],'Effervescence is gas formation; bubbles alone do not identify the gas.')
q(c,'Which standard observation supports identifying the gas as carbon dioxide?','It turns limewater milky.',['It must have a blue colour.','Its presence always makes ethanol strongly basic.','It removes the carboxyl carbon from every remaining acid molecule.'],'Carbon dioxide turns limewater milky in the standard gas test.','Application')
q(c,'In the ordinary comparison, should ethanol show the same acid–carbonate effervescence as ethanoic acid?','No; their complete functional groups have different behaviour.',['Yes, because both contain the letters OH.','Yes, because ethanol is NaOH.','No, because ethanol has no oxygen.'],'A bonded alcohol OH is not the same as the OH in a carboxyl group.','Application')
q(c,'Which set lists all the products in CH₃COOH + NaHCO₃ → … ?','CH₃COONa, H₂O and CO₂',['CH₃CH₂OH, H₂ and O₂','CH₃OH and NaOH only','CO₂ only, with sodium disappearing'],'The salt, water and CO₂ account for the atoms supplied by the acid and hydrogencarbonate.','Challenge')
q(c,'Why is observing bubbles alone insufficient to identify a gas?','Different gases can form bubbles, so an appropriate identification test is needed.',['Bubbles can only ever contain hydrogen.','Bubbles contain no matter.','Every bubbling process is the same chemical reaction.'],'Distinguish the observation, gas formation, from the interpretation, the gas identity.','Challenge')
c='Ethanol oxidation and comparing the families'
q(c,'Which organic product forms in the simplified oxidation of ethanol followed in this class?','Ethanoic acid',['Methanol','Sodium hydroxide','Glucose'],'CH₃CH₂OH + O₂ → CH₃COOH + H₂O.')
q(c,'What happens to the two-carbon skeleton in the ethanol-to-ethanoic-acid conversion?','It remains two carbons long while the end group changes.',['It necessarily becomes a one-carbon skeleton.','It gains four new carbon atoms from oxygen.','All carbon atoms disappear.'],'The alcohol end becomes a carboxyl group; the two carbons are retained.','Application')
q(c,'In the oxidation description used for this conversion, what can oxidation mean?','Gaining oxygen and/or losing hydrogen.',['Always gaining sodium atoms.','Only dissolving without changing bonds.','Adding a position number to a name.'],'The book uses this introductory description for the ethanol conversion.')
q(c,'Which process uses glucose to produce ethanol and CO₂ under the stated oxygen-poor conditions?','Fermentation',['Ethanol oxidation to vinegar','Acid–base neutralisation','Acid–hydrogencarbonate effervescence'],'Do not confuse the different starting substances and conditions.')
q(c,'Which comparison between fermentation and vinegar production is correct?','Fermentation makes ethanol from glucose; the vinegar conversion uses oxygen to oxidise ethanol to ethanoic acid.',['Both always have ethanoic acid as their only product.','Neither changes atom connections.','Both are identical to reacting vinegar with baking soda.'],'Follow the starting molecule and reaction conditions rather than just noticing bubbles.','Application')
q(c,'What does the ordinary reversible arrow ⇌ indicate?','The reaction can proceed in both directions.',['The amounts on both sides must be equal.','No molecules can change.','Carbon atoms do not need to be conserved.'],'The arrow describes possible reaction directions; it is not a statement of equal amounts.')
q(c,'Which statement is a sensible limit of the ethanol example?','Do not assume every alcohol oxidises to the same acid.',['Every alcohol must give ethanoic acid.','Every oxygen-containing molecule is ethanol.','No alcohol can change functional group.'],'The class follows a particular primary-alcohol conversion, not every possible alcohol reaction.','Challenge')
q(c,'How many oxygen atoms are present on the reactant side of CH₃CH₂OH + O₂ → CH₃COOH + H₂O?','Three',['One','Two','Four'],'One O is in ethanol and two are in O₂: three in total.','Application')
q(c,'Which evidence-and-reasoning sequence is most appropriate before using the work mat?','Read the complete group, identify the family, predict behaviour, then compare observations.',['Call any OH-containing substance an alcohol immediately.','Choose a family from bottle colour alone.','Ignore the carbonyl and count only loose hydrogens.'],'The lesson builds structure → family → prediction → evidence → explanation.','Challenge')
q(c,'A formula has OH attached to a carbon that is also double-bonded to O. What is the best classification?','A carboxylic acid with the complete –COOH group.',['An alcohol simply because OH is visible.','Sodium hydroxide.','A carbon-free molecule.'],'The entire carboxyl arrangement, not OH in isolation, determines this classification.','Challenge')
assert len(rows)==60
bank=dict(topicId='y10-alcohols-acids',title='Alcohols and carboxylic acids',categories=list(dict.fromkeys(r['category'] for r in rows)),questions=rows)
(ROOT/'assets/revision/questions/y10-alcohols-acids.json').write_text(json.dumps(bank,ensure_ascii=False,indent=2)+'\n')
print('Built 60 section-exclusive alcohol/carboxylic-acid questions.')
